import { useMemo } from 'react';
import { formatQuantity, formatPrice } from '../../format';
import { useInstrument } from '../../theme/theme-provider';
import type { Instrument, OrderBookSnapshot, Side } from '../../types';
import { cn } from '../../utils';

export interface DomOrder {
  price: number;
  quantity: number;
  side: Side;
}

export interface DomLadderProps {
  book: OrderBookSnapshot;
  instrument?: Partial<Instrument>;
  /** Price levels rendered per side. */
  depth?: number;
  /** Last traded price, highlighted in the price column. */
  lastPrice?: number;
  /** Your working orders, drawn in the outer action columns. */
  orders?: DomOrder[];
  /** Traded volume per price for the session, shown as a centre histogram. */
  volumeAtPrice?: Record<number, number>;
  /** Click a bid/ask cell to work an order at that price. */
  onPlace?: (price: number, side: Side) => void;
  /** Click your own resting order to pull it. */
  onCancel?: (order: DomOrder) => void;
  className?: string;
}

interface Rung {
  price: number;
  bidSize: number;
  askSize: number;
  volume: number;
  myBid: number;
  myAsk: number;
}

/**
 * The depth-of-market ladder: one row per price, static price column, size on
 * either side, click to work an order.
 *
 * This is the layout a futures or equities scalper actually trades from, and it
 * differs from `OrderBook` in the way that matters: the price column does not
 * move. In a book the rows re-sort as liquidity changes and the level under
 * your cursor becomes a different price between intent and click. Here the
 * price axis is fixed, so a click lands where you aimed.
 */
export function DomLadder({
  book,
  instrument,
  depth = 10,
  lastPrice,
  orders = [],
  volumeAtPrice,
  onPlace,
  onCancel,
  className,
}: DomLadderProps) {
  const inst = useInstrument(instrument);
  const sizeDigits = inst.sizePrecision ?? 0;

  const { rungs, peakSize, peakVolume } = useMemo(() => {
    const bestBid = book.bids[0]?.price;
    const bestAsk = book.asks[0]?.price;
    if (bestBid === undefined || bestAsk === undefined) {
      return { rungs: [] as Rung[], peakSize: 1, peakVolume: 1 };
    }

    // Build a continuous price axis in whole ticks around the touch, rather
    // than listing only the levels that currently have size — gaps in the book
    // are information, and a ladder that closes them hides where liquidity
    // actually is not.
    const tick = inst.tickSize;
    const topTicks = Math.round(bestAsk / tick) + depth - 1;
    const bidBySize = new Map(book.bids.map((l) => [Math.round(l.price / tick), l.size]));
    const askBySize = new Map(book.asks.map((l) => [Math.round(l.price / tick), l.size]));
    const myBids = new Map<number, number>();
    const myAsks = new Map<number, number>();
    for (const o of orders) {
      const key = Math.round(o.price / tick);
      const target = o.side === 'buy' ? myBids : myAsks;
      target.set(key, (target.get(key) ?? 0) + o.quantity);
    }

    const out: Rung[] = [];
    let maxSize = 1;
    let maxVolume = 1;
    for (let i = 0; i < depth * 2; i++) {
      const ticks = topTicks - i;
      const price = Number((ticks * tick).toFixed(8));
      const bidSize = bidBySize.get(ticks) ?? 0;
      const askSize = askBySize.get(ticks) ?? 0;
      const volume = volumeAtPrice?.[price] ?? 0;
      maxSize = Math.max(maxSize, bidSize, askSize);
      maxVolume = Math.max(maxVolume, volume);
      out.push({
        price,
        bidSize,
        askSize,
        volume,
        myBid: myBids.get(ticks) ?? 0,
        myAsk: myAsks.get(ticks) ?? 0,
      });
    }
    return { rungs: out, peakSize: maxSize, peakVolume: maxVolume };
  }, [book, depth, inst.tickSize, orders, volumeAtPrice]);

  if (rungs.length === 0) {
    return (
      <div className="text-muted-foreground p-5 text-center text-xs">No book to ladder</div>
    );
  }

  const lastTicks = lastPrice !== undefined ? Math.round(lastPrice / inst.tickSize) : null;
  const cols = volumeAtPrice ? '46px 1fr 70px 1fr 46px' : '46px 1fr 70px 1fr 46px';

  return (
    <div className={cn('flex flex-col font-mono text-[11px] tabular-nums', className)}>
      <div
        className="text-muted-foreground bg-muted grid gap-px border-b px-1 py-1 text-center text-[9px] font-semibold tracking-wider uppercase"
        style={{ gridTemplateColumns: cols }}
      >
        <span>Mine</span>
        <span>Bid</span>
        <span>Price</span>
        <span>Ask</span>
        <span>Mine</span>
      </div>

      {rungs.map((rung) => {
        const isLast = lastTicks !== null && Math.round(rung.price / inst.tickSize) === lastTicks;
        return (
          <div
            key={rung.price}
            className={cn('grid gap-px border-b border-transparent', isLast && 'bg-primary/10')}
            style={{ gridTemplateColumns: cols }}
          >
            {/* Your working bids — click to pull. */}
            <button
              type="button"
              disabled={!rung.myBid || !onCancel}
              aria-label={rung.myBid ? `Cancel bid at ${formatPrice(rung.price, inst.pricePrecision)}` : undefined}
              onClick={() => onCancel?.({ price: rung.price, quantity: rung.myBid, side: 'buy' })}
              className={cn(
                'px-1 text-right',
                rung.myBid
                  ? 'text-up bg-up/20 hover:bg-up/35 cursor-pointer font-semibold'
                  : 'cursor-default',
              )}
            >
              {rung.myBid ? formatQuantity(rung.myBid, sizeDigits) : ''}
            </button>

            {/* Bid size — click to join. */}
            <button
              type="button"
              disabled={!onPlace}
              onClick={() => onPlace?.(rung.price, 'buy')}
              aria-label={`Bid ${formatPrice(rung.price, inst.pricePrecision)} size ${formatQuantity(rung.bidSize, sizeDigits)}`}
              className={cn(
                'relative px-1.5 text-right',
                onPlace ? 'hover:bg-up/20 cursor-pointer' : 'cursor-default',
              )}
            >
              {rung.bidSize > 0 && (
                <>
                  <span
                    aria-hidden="true"
                    className="bg-up/20 pointer-events-none absolute inset-y-px right-0"
                    style={{ width: `${(rung.bidSize / peakSize) * 100}%` }}
                  />
                  <span className="text-up relative">
                    {formatQuantity(rung.bidSize, sizeDigits)}
                  </span>
                </>
              )}
            </button>

            {/* The fixed price axis, with session volume behind it. */}
            <div className="bg-muted/60 relative px-1 text-center font-semibold">
              {rung.volume > 0 && (
                <span
                  aria-hidden="true"
                  className="bg-foreground/10 pointer-events-none absolute inset-y-px left-1/2 -translate-x-1/2"
                  style={{ width: `${(rung.volume / peakVolume) * 100}%` }}
                />
              )}
              <span className={cn('relative', isLast && 'text-primary')}>
                {formatPrice(rung.price, inst.pricePrecision)}
              </span>
            </div>

            {/* Ask size — click to join. */}
            <button
              type="button"
              disabled={!onPlace}
              onClick={() => onPlace?.(rung.price, 'sell')}
              aria-label={`Ask ${formatPrice(rung.price, inst.pricePrecision)} size ${formatQuantity(rung.askSize, sizeDigits)}`}
              className={cn(
                'relative px-1.5 text-left',
                onPlace ? 'hover:bg-down/20 cursor-pointer' : 'cursor-default',
              )}
            >
              {rung.askSize > 0 && (
                <>
                  <span
                    aria-hidden="true"
                    className="bg-down/20 pointer-events-none absolute inset-y-px left-0"
                    style={{ width: `${(rung.askSize / peakSize) * 100}%` }}
                  />
                  <span className="text-down relative">
                    {formatQuantity(rung.askSize, sizeDigits)}
                  </span>
                </>
              )}
            </button>

            <button
              type="button"
              disabled={!rung.myAsk || !onCancel}
              aria-label={rung.myAsk ? `Cancel offer at ${formatPrice(rung.price, inst.pricePrecision)}` : undefined}
              onClick={() => onCancel?.({ price: rung.price, quantity: rung.myAsk, side: 'sell' })}
              className={cn(
                'px-1 text-left',
                rung.myAsk
                  ? 'text-down bg-down/20 hover:bg-down/35 cursor-pointer font-semibold'
                  : 'cursor-default',
              )}
            >
              {rung.myAsk ? formatQuantity(rung.myAsk, sizeDigits) : ''}
            </button>
          </div>
        );
      })}
    </div>
  );
}

import type { Direction } from './types';

/**
 * Formatting helpers. Every number shown in a trading UI is formatted the same
 * way twice: fixed decimals so digits line up in a tabular-nums column, and an
 * explicit sign where direction matters.
 */

const cache = new Map<string, Intl.NumberFormat>();

function nf(min: number, max: number, extra?: Intl.NumberFormatOptions) {
  const key = `${min}:${max}:${extra ? JSON.stringify(extra) : ''}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.NumberFormat('en-US', {
      minimumFractionDigits: min,
      maximumFractionDigits: max,
      ...extra,
    });
    cache.set(key, f);
  }
  return f;
}

/** `1234.5` at precision 2 -> `"1,234.50"`. */
export function formatPrice(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  return nf(precision, precision).format(value);
}

/** Quantity: grouped, trailing zeros trimmed. */
export function formatQuantity(value: number, precision = 0): string {
  if (!Number.isFinite(value)) return '--';
  return nf(0, precision).format(value);
}

/** `1250000` -> `"1.25M"`. Keeps size columns to four glyphs. */
export function formatCompact(value: number, digits = 2): string {
  if (!Number.isFinite(value)) return '--';
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  const units: Array<[number, string]> = [
    [1e12, 'T'],
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'K'],
  ];
  for (const [scale, suffix] of units) {
    if (abs >= scale) {
      const scaled = abs / scale;
      // Keep three significant digits: 1.25M, 12.5M, 125M.
      const d = scaled >= 100 ? 0 : scaled >= 10 ? 1 : digits;
      return `${sign}${nf(0, d).format(scaled)}${suffix}`;
    }
  }
  return `${sign}${nf(0, abs < 1 ? digits : 0).format(abs)}`;
}

/** `0.0421` -> `"+4.21%"`. Input is a ratio, not percentage points. */
export function formatPercent(ratio: number, precision = 2, signed = true): string {
  if (!Number.isFinite(ratio)) return '--';
  const pct = ratio * 100;
  const sign = signed && pct > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(pct)}%`;
}

/** Absolute change with a forced sign so gains and losses align. */
export function formatSigned(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(value)}`;
}

/** `hh:mm:ss` in local time - the tape's only useful resolution. */
export function formatTime(time: number | Date, withMillis = false): string {
  const d = time instanceof Date ? time : new Date(time);
  const base = d.toTimeString().slice(0, 8);
  if (!withMillis) return base;
  return `${base}.${String(d.getMilliseconds()).padStart(3, '0')}`;
}

/** Axis-friendly timestamp: drops seconds, adds the date when it changes. */
export function formatAxisTime(time: number, showDate = false): string {
  const d = new Date(time);
  const hhmm = d.toTimeString().slice(0, 5);
  if (!showDate) return hhmm;
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/** Signed money, e.g. `-$1,204.50`. */
export function formatMoney(value: number, currency = '$', precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value < 0 ? '-' : '';
  return `${sign}${currency}${nf(precision, precision).format(Math.abs(value))}`;
}

/** Direction of `value` relative to `reference` (default zero). */
export function directionOf(value: number, reference = 0): Direction {
  if (!Number.isFinite(value) || value === reference) return 'flat';
  return value > reference ? 'up' : 'down';
}

/** The `tu-up` / `tu-down` / `tu-flat` class for a direction. */
export function directionClass(direction: Direction): string {
  return `tu-${direction}`;
}

/** `+` / `-` glyphs used by DeltaBadge and the tape. */
export function directionArrow(direction: Direction): string {
  return direction === 'up' ? '▲' : direction === 'down' ? '▼' : '–';
}

/** Round to the instrument's tick so UI-entered prices are always valid. */
export function roundToTick(price: number, tickSize: number): number {
  if (!tickSize || tickSize <= 0) return price;
  const ticks = Math.round(price / tickSize);
  // Re-round after dividing to shake off float dust (0.1 * 3 = 0.30000000000000004).
  const decimals = decimalsOf(tickSize);
  return Number((ticks * tickSize).toFixed(decimals));
}

/** Decimal places implied by a tick size: `0.01` -> 2, `0.5` -> 1, `5` -> 0. */
export function decimalsOf(tickSize: number): number {
  if (!Number.isFinite(tickSize) || tickSize <= 0) return 2;
  const s = tickSize.toString();
  if (s.includes('e-')) return Number(s.split('e-')[1]);
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export type TimeInForce = 'day' | 'gtc' | 'ioc' | 'fok';

export interface Order extends OrderDraft {
  id: string;
  time: number;
  status: OrderStatus;
  filledQuantity: number;
  avgFillPrice?: number;
}

/** Price/size formatting rules for an instrument. */
export interface Instrument {
  symbol: string;
  name?: string;
  /** Decimal places for price. */
  pricePrecision: number;
  /** Minimum price increment. */
  tickSize: number;
  /** Decimal places for quantity. */
  sizePrecision?: number;
  /** Quote-currency symbol, e.g. "$". */
  currency?: string;
}

import {
  createContext,
  useContext,
  useMemo,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { TooltipProvider } from '../components/ui/tooltip';
import type { Instrument } from '../types';
import { cn } from '../utils';

export type ThemeName = 'dark' | 'light';
export type DirectionPalette = 'classic' | 'colorblind';

export interface TradingTheme {
  theme: ThemeName;
  /** `classic` is green/red; `colorblind` is blue/amber. */
  palette: DirectionPalette;
  /** Formatting defaults for components not given their own instrument. */
  instrument: Instrument;
}

export const defaultInstrument: Instrument = {
  symbol: '',
  pricePrecision: 2,
  tickSize: 0.01,
  sizePrecision: 0,
  currency: '$',
};

const ThemeContext = createContext<TradingTheme>({
  theme: 'dark',
  palette: 'classic',
  instrument: defaultInstrument,
});

export function useTradingTheme(): TradingTheme {
  return useContext(ThemeContext);
}

/**
 * Resolves the instrument a component formats with: its own prop wins, then
 * the provider's, then the library default.
 */
export function useInstrument(override?: Partial<Instrument>): Instrument {
  const { instrument } = useTradingTheme();
  return useMemo(
    () => (override ? { ...instrument, ...override } : instrument),
    [instrument, override],
  );
}

export interface TradingProviderProps {
  children: ReactNode;
  theme?: ThemeName;
  palette?: DirectionPalette;
  instrument?: Partial<Instrument>;
  /** Token overrides, e.g. `{ '--primary': '#ff8a00' }`. */
  tokens?: Record<string, string>;
  /**
   * Skip the wrapper element and inherit whatever theme the host already
   * applies. Use this inside an existing shadcn app that owns `.dark` itself.
   */
  inherit?: boolean;
  className?: string;
  style?: CSSProperties;
}

/**
 * Scopes theme, direction palette and instrument defaults to a subtree.
 *
 * Deliberately not a global stylesheet switch: two providers can coexist, so a
 * light-themed report can sit inside a dark terminal. Also mounts a single
 * Radix TooltipProvider so every tooltip in the tree shares one delay timer.
 */
export function TradingProvider({
  children,
  theme = 'dark',
  palette = 'classic',
  instrument,
  tokens,
  inherit = false,
  className,
  style,
}: TradingProviderProps) {
  const value = useMemo<TradingTheme>(
    () => ({ theme, palette, instrument: { ...defaultInstrument, ...instrument } }),
    [theme, palette, instrument],
  );

  const content = <TooltipProvider>{children}</TooltipProvider>;

  return (
    <ThemeContext.Provider value={value}>
      {inherit ? (
        content
      ) : (
        <div
          data-tu-theme={theme}
          data-tu-palette={palette}
          className={cn(
            'bg-background text-foreground',
            theme === 'dark' && 'dark',
            className,
          )}
          style={{ ...(tokens as CSSProperties | undefined), ...style }}
        >
          {content}
        </div>
      )}
    </ThemeContext.Provider>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
